#!/bin/sh
# DJAEGER Gemini Whole-System Advisor. Contextual reasoning only; execution remains local and typed.
. /usr/lib/djaeger-modem/investigator.sh
umask 077
GEMINI_DIR=/root/djaeger-modem/gemini; GEMINI_KEY=$GEMINI_DIR/api.key; GEMINI_STATE=$GEMINI_DIR/advisor.state; GEMINI_MEMORY=$GEMINI_DIR/insights.csv
mkdir -p "$GEMINI_DIR"; chmod 700 "$GEMINI_DIR" 2>/dev/null
[ -f "$GEMINI_MEMORY" ] || echo 'epoch,state,root_domain,local_risk,system_risk,insight' > "$GEMINI_MEMORY"; chmod 600 "$GEMINI_MEMORY" 2>/dev/null
gemini_enabled(){ [ "$(uciopt gemini_enabled 0)" = 1 ] && [ -s "$GEMINI_KEY" ]; }; gemini_set_key(){ cat > "$GEMINI_KEY"; chmod 600 "$GEMINI_KEY"; }; gemini_clear_key(){ rm -f "$GEMINI_KEY"; }; gemini_key_status(){ [ -s "$GEMINI_KEY" ] && echo CONFIGURED || echo NOT_CONFIGURED; }; gemini_state_get(){ sed -n "s/^$1=//p" "$GEMINI_STATE" 2>/dev/null | head -n1; }; json_escape(){ printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g' | tr '\n\r\t' '   '; }; safe_diag(){ printf '%s' "$1" | tr '\n\r\t' '   ' | tr -cd 'A-Za-z0-9 _.,:=+/%@#;()\[\]-' | cut -c1-240; }; gemini_write_state(){ printf 'updated=%s\nstatus=%s\napi_code=%s\napi_status=%s\napi_message=%s\ncontext_state=%s\ncontext_root_domain=%s\ncontext_incident_start=%s\nadvice=%s\n' "$(date +%s)" "$1" "${GAPI_CODE:-NONE}" "${GAPI_STATUS:-NONE}" "${GAPI_MESSAGE:-NONE}" "${CUR:-UNKNOWN}" "${ROOT_DOMAIN:-UNKNOWN}" "${INCIDENT_START:-0}" "$2" > "$GEMINI_STATE.tmp"; chmod 600 "$GEMINI_STATE.tmp"; mv "$GEMINI_STATE.tmp" "$GEMINI_STATE"; }
gemini_history_summary(){ HGOOD="$(tail -n 300 /root/djaeger-modem/system-health.csv 2>/dev/null | awk -F, 'NR>1{n++;l+=$2;m+=$4;c+=$5;r+=$6} END{if(n)printf "healthy_samples=%d avg_load100=%d avg_memavail_pct=%d avg_conntrack_pct=%d avg_rootfs_pct=%d",n,l/n,m/n,c/n,r/n;else print "healthy_samples=0"}')"; RECENT="$(tail -n 6 /root/djaeger-modem/incidents.csv 2>/dev/null | tr '\n' '|' | cut -c1-600)"; OUT="$(tail -n 8 /root/djaeger-modem/recovery-outcomes.csv 2>/dev/null | tr '\n' '|' | cut -c1-700)"; printf '%s recent_incidents=%s recovery_outcomes=%s' "$HGOOD" "$RECENT" "$OUT"; }
gemini_advise(){ GAPI_CODE=NONE; GAPI_STATUS=NONE; GAPI_MESSAGE=NONE; gemini_enabled || return 0; command -v curl >/dev/null 2>&1 || { gemini_write_state NO_CURL NONE; return 0; }; command -v jsonfilter >/dev/null 2>&1 || { gemini_write_state NO_JSONFILTER NONE; return 0; }; MODEL="$(uciopt gemini_model gemini-3.6-flash)"; TIMEOUT="$(uciopt gemini_timeout 20)"; KEY="$(cat "$GEMINI_KEY" 2>/dev/null)"; [ -n "$KEY" ] || return 0; HIST="$(gemini_history_summary)"; EVIDENCE=''; case "$CUR" in OUTAGE|RECOVERING) EVIDENCE="$(investigator_summary)";; *) if [ "${AI_RISK:-0}" -ge 60 ] 2>/dev/null || [ "${SYS_RISK:-0}" -ge 50 ] 2>/dev/null; then EVIDENCE="$(investigator_summary)"; fi;; esac
PROMPT="You are DJAEGER Whole-System Connectivity Investigator and recovery recommender. Goal: maximize long-term Internet stability. Sanitized root evidence is READ-ONLY. Correlate cellular radio, Huawei service/data session, WAN/netifd, routing, DNS, conntrack, resource pressure, USB/driver/kernel events, services and interface counters. Distinguish correlation from causation. Never request identifiers, credentials, shell commands, arbitrary code, paths, URLs, factory reset or unrestricted actions. You may recommend exactly one typed ACTION from NONE,WAN_RECONNECT,NETIFD_RESTART,DNSMASQ_RESTART,MODEM_REBOOT. Prefer least disruptive action. MODEM_REBOOT only when evidence strongly indicates modem/cellular/session failure and softer recovery is inadequate. Local broker independently validates domain, outage state, policy locks, cooldown and budget before execution. Return exactly DIAGNOSIS=<category>;CONFIDENCE=<0-100>;ACTION=<allowed action>;EVIDENCE=<short>;ADVICE=<short>;HEALTH_INSIGHT=<healthy pattern>. state=$CUR root=${ROOT_DOMAIN:-UNKNOWN} reason=${ROOT_REASON:-$CAUSE} incident_start=${INCIDENT_START:-0} localrisk=${AI_RISK:-0} sysrisk=${SYS_RISK:-0} sysreason=${SYS_REASON:-UNKNOWN} modem=$MODEM_OK service=$SERVICE sim=$SIM conn=$CONN rsrp=$RSRP rsrq=$RSRQ sinr=$SINR gw=$GWOK internet=$INET dns=$DNSOK wan=${WAN_UP:-0} route=${ROUTE_OK:-0} dnsmasq=${DNSMASQ_OK:-0} ct=${CTPCT:-0} load=${LOAD100:-0} mempct=${MEMPCT:-0} rootfspct=${ROOTPCT:-0} usb=${USB_PRESENT:-0} kerr=${KERR:-0}. history=$HIST root_evidence=$EVIDENCE"
BODY="{\"model\":\"$(json_escape "$MODEL")\",\"store\":false,\"input\":\"$(json_escape "$PROMPT")\"}"; ERR="$GEMINI_DIR/curl.err"; : > "$ERR"; chmod 600 "$ERR"; HTTP="$(curl -sS --connect-timeout 8 --max-time "$TIMEOUT" -o "$GEMINI_DIR/response.tmp" -w '%{http_code}' -H 'Content-Type: application/json' -H "x-goog-api-key: $KEY" --data-binary "$BODY" 'https://generativelanguage.googleapis.com/v1beta/interactions' 2>"$ERR")"; RC=$?; KEY=''; unset KEY; RESP="$(cat "$GEMINI_DIR/response.tmp" 2>/dev/null)"; rm -f "$GEMINI_DIR/response.tmp"; if [ "$RC" -ne 0 ]; then GAPI_CODE="CURL_$RC"; GAPI_STATUS=TRANSPORT; GAPI_MESSAGE="$(safe_diag "$(cat "$ERR" 2>/dev/null)")"; [ -n "$GAPI_MESSAGE" ] || GAPI_MESSAGE=NO_RESPONSE; rm -f "$ERR"; gemini_write_state TRANSPORT_ERROR NONE; return 0; fi; rm -f "$ERR"; [ -n "$RESP" ] || { GAPI_CODE="HTTP_${HTTP:-000}"; GAPI_STATUS=EMPTY_RESPONSE; GAPI_MESSAGE=NO_RESPONSE; gemini_write_state TRANSPORT_ERROR NONE; return 0; }; CODE="$(printf '%s' "$RESP" | jsonfilter -e '@.error.code' 2>/dev/null | head -n1)"; if [ -n "$CODE" ] || [ "${HTTP:-000}" -ge 400 ] 2>/dev/null; then GAPI_CODE="$(safe_diag "${CODE:-HTTP_$HTTP}")"; GAPI_STATUS="$(safe_diag "$(printf '%s' "$RESP" | jsonfilter -e '@.error.status' 2>/dev/null | head -n1)")"; GAPI_MESSAGE="$(safe_diag "$(printf '%s' "$RESP" | jsonfilter -e '@.error.message' 2>/dev/null | head -n1)")"; [ -n "$GAPI_STATUS" ] || GAPI_STATUS="HTTP_$HTTP"; [ -n "$GAPI_MESSAGE" ] || GAPI_MESSAGE=API_ERROR_RESPONSE; case "${CODE:-$HTTP}" in 400) ST=BAD_REQUEST;;401|403) ST=AUTH_OR_PERMISSION;;404) ST=MODEL_OR_ENDPOINT_NOT_FOUND;;429) ST=RATE_LIMITED;;500|502|503|504) ST=SERVER_ERROR;;*) ST=API_ERROR;;esac; gemini_write_state "$ST" NONE; return 0; fi; TEXT="$(printf '%s' "$RESP" | jsonfilter -e '@.steps[@.type="model_output"].content[@.type="text"].text' 2>/dev/null | head -n1 | tr '\n\r' '  ' | cut -c1-900)"; [ -n "$TEXT" ] || TEXT="$(printf '%s' "$RESP" | jsonfilter -e '@.output_text' 2>/dev/null | head -n1 | tr '\n\r' '  ' | cut -c1-900)"; [ -n "$TEXT" ] || { GAPI_CODE="HTTP_${HTTP:-200}"; GAPI_STATUS=EMPTY_OUTPUT; GAPI_MESSAGE=NO_MODEL_TEXT; gemini_write_state UNPARSEABLE_RESPONSE NONE; return 0; }; SAFE="$(printf '%s' "$TEXT" | tr -cd 'A-Za-z0-9 _.,:=+/%@#;()-' | tr ',' '.' | tr ' ' '_' | cut -c1-900)"; [ -n "$SAFE" ] || SAFE=NONE; gemini_write_state OK "$SAFE"; printf '%s,%s,%s,%s,%s,%s\n' "$(date +%s)" "${CUR:-UNKNOWN}" "${ROOT_DOMAIN:-UNKNOWN}" "${AI_RISK:-0}" "${SYS_RISK:-0}" "$SAFE" >> "$GEMINI_MEMORY"; L="$(awk 'END{print NR+0}' "$GEMINI_MEMORY" 2>/dev/null)"; [ "${L:-0}" -gt 1001 ] && { head -n1 "$GEMINI_MEMORY" > "$GEMINI_MEMORY.new"; tail -n 1000 "$GEMINI_MEMORY" >> "$GEMINI_MEMORY.new"; chmod 600 "$GEMINI_MEMORY.new"; mv "$GEMINI_MEMORY.new" "$GEMINI_MEMORY"; }; }
gemini_status(){ echo "Gemini      : $([ "$(uciopt gemini_enabled 0)" = 1 ] && echo ENABLED || echo DISABLED)"; echo "API Key     : $(gemini_key_status)"; echo "Model       : $(uciopt gemini_model gemini-3.6-flash)"; if [ -f "$GEMINI_STATE" ]; then echo "Advisor     : $(gemini_state_get status)"; C="$(gemini_state_get api_code)"; S="$(gemini_state_get api_status)"; M="$(gemini_state_get api_message)"; [ -n "$C$S$M" ] && [ "$C$S$M" != NONENONENONE ] && { echo "API Code    : ${C:-NONE}"; echo "API Status  : ${S:-NONE}"; echo "API Message : ${M:-NONE}"; }; echo "Last Insight: $(gemini_state_get advice)"; else echo 'Advisor     : NOT_RUN'; fi; }
